use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

const MAX_QUESTION_CHARS: usize = 512;
const MAX_TOOL_ROUNDS: usize = 3;
const SYSTEM: &str = "You are a customer support assistant. Answer using the provided \
    knowledge. You may ask for the 'lookup' tool to search the knowledge base.";

struct Node;

fn fail(message: &str) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.to_string(),
    })
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // Precondition from the contract: len(question) <= 512.
        // Checked again here so a violation becomes an error value, not a bad call.
        if ctx.question.chars().count() > MAX_QUESTION_CHARS {
            return fail("question exceeds 512 characters");
        }

        let knowledge = ctx.knowledge.join("\n- ");
        let prompt = format!(
            "Intent: {}\nQuestion: {}\nKnowledge:\n- {}\n",
            intent_label(ctx.intent),
            ctx.question,
            knowledge,
        );

        let mut lookups = String::new();
        for _ in 0..MAX_TOOL_ROUNDS {
            let full_prompt = if lookups.is_empty() {
                prompt.clone()
            } else {
                format!("{prompt}\nLookup results:\n{lookups}")
            };

            match tool_llm::generate(SYSTEM, &full_prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(request) => {
                    // Only the granted tool is callable; anything else is refused.
                    if request.tool != "lookup" {
                        return fail("model requested a tool outside the node's scope");
                    }
                    let hits = kb_read::lookup(&request.query);
                    lookups.push_str(&format!("query: {}\n", request.query));
                    for hit in hits {
                        lookups.push_str("- ");
                        lookups.push_str(&hit);
                        lookups.push('\n');
                    }
                }
            }
        }

        fail("tool-call budget exhausted without a text answer")
    }
}

export!(Node);
